(** ** What this board establishes

    42 of 42 arms of the certificate are re-derived by the kernel and
    sound: each [sound_*] is a theorem that the machine, from that arm's
    left-hand side and against any tail the flags permit, reaches the arm's
    right-hand side in exactly the certificate's step count. *)

(** ** The closure: from the RULES to [NeverQuasiHaltsSt]

    The arms below are the case split of [LadderCheck.digs_decomp], built
    from the FAMILY rather than mined: interior arms for the digits below the
    top, and fill arms.  Every certificate arm above is one of these with its
    run lengths pinned to their lower bounds, which is why 42 of them
    collapse to 2 here.

    Both classes are indexed by [LadderCheck]'s ONE arm scheme -- flat below
    a threshold, residue-and-stride at or above it.  The interior class runs
    at threshold 0 stride 1, the fill class at threshold 1
    stride 1.

    [board_neverqh] consumes them, the boot, and one chain per state per fill
    arm, and returns the machine-level theorem. *)
Definition iarm0_0_1RB0RD_0LC0RA_1RA1LC_1LD0LC : LRule :=
  mkLRule (mkC StB (mkS [] [S1;S1;S1] 1 0 [S1;S1;S0]) S0 (mkS [S1;S1;S1;S1;S1;S1;S1] [] 0 0 []))
          (mkC StB (mkS [] [S1;S1;S0] 1 0 [S1;S1;S1]) S0 (mkS [S1;S1;S1;S1;S1;S1;S1] [] 0 0 [])) 8 8.
Definition ch_iarm0_0_1RB0RD_0LC0RA_1RA1LC_1LD0LC : list rstep := [RB (SRotL 1);RB (SWin 1);RB (SCycL 3 0);RB (SWin 6);RB (SCycR 5);RB (SWin 1);RB (SUnrotL 1)].
Lemma ok_iarm0_0_1RB0RD_0LC0RA_1RA1LC_1LD0LC :
  check_arm tm false true rules iarm0_0_1RB0RD_0LC0RA_1RA1LC_1LD0LC
            ch_iarm0_0_1RB0RD_0LC0RA_1RA1LC_1LD0LC = true.
Proof. vm_compute. reflexivity. Qed.

Definition iarm_1RB0RD_0LC0RA_1RA1LC_1LD0LC (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB0RD_0LC0RA_1RA1LC_1LD0LC
  | _, _ => iarm0_0_1RB0RD_0LC0RA_1RA1LC_1LD0LC   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

Definition farm1_0_1RB0RD_0LC0RA_1RA1LC_1LD0LC : LRule :=
  mkLRule (mkC StB (mkS [S1;S1;S1] [S1;S1;S1] 1 0 [S1;S1;S1]) S0 (mkS [S1;S1;S1;S1;S1;S1;S1] [] 0 0 []))
          (mkC StB (mkS [S1;S1;S0;S1;S1;S1] [S1;S1;S0] 1 0 [S1;S1;S1]) S0 (mkS [S1;S1;S1;S1;S1;S1;S1] [] 0 0 [])) 8 114.
Definition ch_farm1_0_1RB0RD_0LC0RA_1RA1LC_1LD0LC : list rstep := [RB (SWin 3);RB (SCycL 3 0);RB (SWin 3);RB (SWinL 7);RB (SCycR 5);RB (SWin 16);RB (SWinR 74);RB (SRotL 1);RB (SWin 11)].
Lemma ok_farm1_0_1RB0RD_0LC0RA_1RA1LC_1LD0LC :
  check_arm tm true true rules farm1_0_1RB0RD_0LC0RA_1RA1LC_1LD0LC
            ch_farm1_0_1RB0RD_0LC0RA_1RA1LC_1LD0LC = true.
Proof. vm_compute. reflexivity. Qed.

(** The fill arms, one per arm index and PHASE.  Both tails are known
    empty -- they are the only arms that see the end of the counter -- and
    the arm at index [r] has [r] guaranteed block copies materialised into
    [s_pre], without which it has no chain at all.  [fm1]/[fm2] say how the
    fill target's own guaranteed copies divide about the block.

    The phase is the second index because the fill arm is the ONLY one that
    sees a terminator: it leaves from the terminator of its own phase and
    lands on the terminator of the phase its law names.  The interior arms
    keep the terminator in the opaque tail and are phase-free. *)
Definition farm_1RB0RD_0LC0RA_1RA1LC_1LD0LC (r ph : nat) : LRule :=
  match r, ph with
  | 1, 0 => farm1_0_1RB0RD_0LC0RA_1RA1LC_1LD0LC
  | _, _ => farm1_0_1RB0RD_0LC0RA_1RA1LC_1LD0LC  (* unreachable: 0 < r < N0 + st *)
  end.

Definition fm1_1RB0RD_0LC0RA_1RA1LC_1LD0LC (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 0 | _, _ => 0 end.
Definition fm2_1RB0RD_0LC0RA_1RA1LC_1LD0LC (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 0 | _, _ => 0 end.

(** One chain per UNPINNED INSTRUCTION per fill arm, at the VISIT PHASE
    0.  [fire_of_run_instr] turns each into a fire of that instruction,
    and [tops_cofinal_at] says the tops of that phase keep coming.  The fill
    arm is the counter's overflow, so this is where the rare instruction of
    a sparse row is witnessed. *)
Definition vis_1RB0RD_0LC0RA_1RA1LC_1LD0LC (r : nat) (t : Instr) : list lstep :=
  match r, t with
  | 1, (StA, S0) => [SWin 3;SCycL 3 0;SWinL 8]
  | 1, (StA, S1) => [SWin 3;SCycL 3 0;SWinL 5]
  | 1, (StB, S0) => []
  | 1, (StB, S1) => [SWin 3;SCycL 3 0;SWinL 9]
  | 1, (StC, S0) => [SWin 3;SCycL 3 0;SWinL 4]
  | 1, (StC, S1) => [SWin 1]
  | 1, (StD, S0) => [SWin 3;SCycL 3 0;SWin 3;SWinL 7;SCycR 5;SWinR 22]
  | 1, (StD, S1) => [SWin 3;SCycL 3 0;SWinL 6]
  | _, _ => []
  end.

Lemma iarm_sound_1RB0RD_0LC0RA_1RA1LC_1LD0LC : forall d r,
  d < fm_b FAM - 1 -> r < 0 + 1 ->
  RuleSound tm (negb (fm_left FAM)) (fm_left FAM) (iarm_1RB0RD_0LC0RA_1RA1LC_1LD0LC d r).
Proof.
  intros d r Hd Hr. vm_compute in Hd.
  destruct d as [|d].
  {
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB0RD_0LC0RA_1RA1LC_1LD0LC | exact ok_iarm0_0_1RB0RD_0LC0RA_1RA1LC_1LD0LC]. }
    exfalso; lia.
  }
  exfalso; lia.
Qed.

Lemma iarm_lhs_1RB0RD_0LC0RA_1RA1LC_1LD0LC : forall d r,
  d < fm_b FAM - 1 -> r < 0 + 1 ->
  lr_lhs (iarm_1RB0RD_0LC0RA_1RA1LC_1LD0LC d r)
    = cls_conf FAM (cls_side FAM [] (fm_b FAM - 1) r
                      (astride 0 1 r) [d]).
Proof.
  intros d r Hd Hr. vm_compute in Hd.
  destruct d as [|d].
  {
