Proof. vm_compute. reflexivity. Qed.

Definition iarm_1RB1LA_0LA1RC_0LC1RD_0RB0RB (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB1LA_0LA1RC_0LC1RD_0RB0RB
  | 0, 1 => iarm0_1_1RB1LA_0LA1RC_0LC1RD_0RB0RB
  | _, _ => iarm0_0_1RB1LA_0LA1RC_0LC1RD_0RB0RB   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

Definition farm1_0_1RB1LA_0LA1RC_0LC1RD_0RB0RB : LRule :=
  mkLRule (mkC StB (mkS [S1;S1;S1] [S1;S1;S1] 1 0 [S1]) S0 (mkS [] [] 0 0 []))
          (mkC StB (mkS [S0;S1;S1;S1;S1;S1] [S0;S1;S1] 1 0 [S1]) S0 (mkS [] [] 0 0 [])) 6 22.
