Lemma farm_rhs_1RB1LA_0LA1RC_0LC1RD_0RB0RB : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 1 ->
  lr_rhs (farm_1RB1LA_0LA1RC_0LC1RD_0RB0RB r ph)
    = cls_conf FAM (run_side FAM (f_mid (fam_fill FAM ph)) (fm1_1RB1LA_0LA1RC_0LC1RD_0RB0RB r ph)
                      (astride 1 1 r) (fm2_1RB1LA_0LA1RC_0LC1RD_0RB0RB r ph)
                      (f_to (fam_fill FAM ph))
                      (f_pre (fam_fill FAM ph)) (f_suf (fam_fill FAM ph))).
Proof.
