  | StC, S1 => mk S0 DL StB
  | StD, S0 => mk S0 DR StB
  | StD, S1 => mk S0 DR StB
  end.
(** the instructions the machine never fires; the whole board runs
    on the machine wrapped at them, where firing one halts *)
Definition pins_1RB1LA_0LA1RC_1RD0LB_0RB0RB : list Instr := [].
Local Notation tm := (tm_wrap_trs tm_1RB1LA_0LA1RC_1RD0LB_0RB0RB pins_1RB1LA_0LA1RC_1RD0LB_0RB0RB).

(** ** The family, as DATA

    The successor is a PARAMETER here, not a law: [fam_succ] reads the fill
    of the phase it is in, the code the digits are written in, and the step
    the counter advances by, all off this record. *)
Definition fam_1RB1LA_0LA1RC_1RD0LB_0RB0RB : Fam := mkFam 2 [[S0;S1;S1];[S1;S1;S1]] [] [[S1]] Binary 1 [mkFill 1 [] 0 [] 0] StB S0 true [].
Local Notation FAM := fam_1RB1LA_0LA1RC_1RD0LB_0RB0RB.

(** ** The ladder, as DATA

    2 window rule(s).  [check_ladder] validates rule i against rules
    0..i-1 only, and [rule_sound] -- ONE theorem, by induction on ladder
    POSITION -- turns that into soundness for all of them. *)
Definition lad_1RB1LA_0LA1RC_1RD0LB_0RB0RB : list (LRule * list rstep) :=
  [(mkLRule (mkC StA (mkS [S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) (mkC StA (mkS [] [] 0 0 []) S1 (mkS [S1] [] 0 0 [])) 0 1, [RB (SWin 1)]);
   (mkLRule (mkC StB (mkS [] [] 0 0 []) S1 (mkS [S1;S1;S1] [] 0 0 [])) (mkC StB (mkS [S0;S1;S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) 0 5, [RB (SWin 5)])].
Local Notation lad := lad_1RB1LA_0LA1RC_1RD0LB_0RB0RB.

Definition rules_1RB1LA_0LA1RC_1RD0LB_0RB0RB : list LRule := map fst lad.
Local Notation rules := rules_1RB1LA_0LA1RC_1RD0LB_0RB0RB.

Lemma ladder_ok_1RB1LA_0LA1RC_1RD0LB_0RB0RB : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_1RB1LA_0LA1RC_1RD0LB_0RB0RB : Forall (RuleSound tm false false) rules.
Proof. apply rule_sound_nil. exact ladder_ok_1RB1LA_0LA1RC_1RD0LB_0RB0RB. Qed.

