Proof. vm_compute. reflexivity. Qed.

Definition iarm_1RB1LA_0LA1RC_1RD0LB_1LA0RB (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB1LA_0LA1RC_1RD0LB_1LA0RB
  | 0, 1 => iarm0_1_1RB1LA_0LA1RC_1RD0LB_1LA0RB
  | _, _ => iarm0_0_1RB1LA_0LA1RC_1RD0LB_1LA0RB   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

Definition farm1_0_1RB1LA_0LA1RC_1RD0LB_1LA0RB : LRule :=
